def _parse_expression(self, inTemplate: bool) -> ASTExpression:
    # -> assignment-expression
    #  | expression "," assignment-expresion
    left_expression = self._parse_assignment_expression(inTemplate=inTemplate)
    if self._lookahead_is_comma():
        self._consume_comma()
        right_expression = self._parse_assignment_expression(inTemplate=inTemplate)
        return ASTExpression(left=left_expression, right=right_expression)
    return left_expression
